// The Worker's entry point (wrangler.jsonc "main"): the OpenNext build of the
// app (.open-next/worker.js, written by `opennextjs-cloudflare build`) plus
// the Cron Trigger, which runs /api/cron/reminders in-process every 15 minutes.

// Generated by the build, so it is missing before one.
// eslint-disable-next-line @typescript-eslint/ban-ts-comment
// @ts-ignore
import openNext from '../.open-next/worker.js'

type Env = CloudflareEnv & { CRON_SECRET?: string }
type FetchHandler = { fetch(request: Request, env: Env, ctx: ExecutionContext): Promise<Response> }

const app = openNext as FetchHandler

// Handled in-process, so the host never resolves; OpenNext needs the host
// header to match it or it treats the request as external.
const INTERNAL_HOST = 'worker.internal'

export default {
  fetch(request, env, ctx) {
    return app.fetch(request, env, ctx)
  },

  async scheduled(_controller, env, ctx) {
    if (!env.CRON_SECRET) throw new Error('CRON_SECRET is not set')
    const request = new Request(`https://${INTERNAL_HOST}/api/cron/reminders`, {
      method: 'POST',
      headers: { host: INTERNAL_HOST, authorization: `Bearer ${env.CRON_SECRET}` },
    })
    const response = await app.fetch(request, env, ctx)
    // A failed run throws, so Cloudflare records the cron run as failed.
    if (!response.ok) throw new Error(`reminders failed with status ${response.status}`)
  },
} satisfies ExportedHandler<Env>
